export type Source = "career_page" | "linkedin" | "indeed";

export type JobDraft = {
  source: Source;
  sourceUrl: string;
  companyName: string;
  title: string;
  location: string | null;
  remote: "remote" | "hybrid" | "onsite" | "unknown";
  descriptionHtml: string;
  applyUrl: string;
