  margin-left: auto;
  margin-right: auto;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: var(--muted);
  font-size: 0.88rem;
}

.site-footer nav {
  display: flex;
  gap: 16px;
}

.site-footer a {
  text-decoration: none;
}

main {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 32px 24px 72px;
  flex: 1;
}

main > header {
  margin-bottom: 28px;
}

h1,
h2,
h3 {
  letter-spacing: -0.045em;
  line-height: 1.12;
  font-weight: 650;
}

h1 {
  font-size: clamp(2rem, 4vw, 3.1rem);
  margin: 0 0 12px;
}

h2 {
  font-size: 1.25rem;
  margin: 0 0 12px;
}

h3 {
