}

.filters label:has(input[type="checkbox"]) input {
  width: auto;
}

.filters button {
  grid-column: -2 / -1;
  align-self: end;
}

.job-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.job-card {
  display: grid;
  gap: 8px;
  padding: 18px 18px 16px;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.job-card:hover {
  border-color: rgb(196 163 90 / 0.35);
  background: var(--bg-hover);
}

.job-card h2 a,
.job-card h3 a {
  text-decoration: none;
}

.job-card h2 a:hover,
.job-card h3 a:hover {
  color: var(--accent);
}

.job-meta {
  margin: 0;
