    Write-Output 'AGENT_LOOP_WAKE_fablecommit {"prompt":"Fable idle. Copia la chat Cursor in docs/handoff/, committa TUTTI i file progetto (no .env/node_modules/.next/.open-next/.superpowers/sdd), push origin main, poi ferma questo loop."}'
    break
  }
}
